"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["94957"],{62671(e,n,t){t.r(n),t.d(n,{metadata:()=>o,default:()=>u,frontMatter:()=>r,contentTitle:()=>s,toc:()=>h,assets:()=>l});var o=JSON.parse('{"id":"maopoetry","title":"","description":"2006/2/9 1530","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/maopoetry.md","sourceDirName":".","slug":"/maopoetry","permalink":"/en/maopoetry","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"maopoetry","title":"","hide_table_of_contents":true,"sidebar_label":"One Person\'s View \u2014 A Brief Review of Mao Runzhi\'s Poetry (2006/2/9 15:03:30)"},"sidebar":"timelineSidebar","previous":{"title":"Serial 3: That Night, His Body Fluids Sprayed All Over Me (2006/2/9 10:17:30)","permalink":"/en/timeline/fluid/03"},"next":{"title":"Old China Still Had the \\"Draft History of Qing\\" \u2014 What About New China\'s \\"History of the Republic\\"? (2006/2/9 16:19:05)","permalink":"/en/timeline/confucius/20060209"}}'),i=t(74848),a=t(28453);let r={id:"maopoetry",title:"",hide_table_of_contents:!0,sidebar_label:"One Person's View \u2014 A Brief Review of Mao Runzhi's Poetry (2006/2/9 15:03:30)"},s="A Personal View: A Brief Critique of the Poetry of Mr. Mao Runzhi",l={},h=[];function d(e){let n={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"a-personal-view-a-brief-critique-of-the-poetry-of-mr-mao-runzhi",children:"A Personal View: A Brief Critique of the Poetry of Mr. Mao Runzhi"})}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"2006/2/9 15:03:30"}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"The way of poetry is not about talent and learning, though talent and learning are certainly indispensable. The world has no shortage of those with great talent and vast learning, yet most of their poetry is not worth preserving -- they are constrained by temperament. Mr. Mao Runzhi, in his youth, genuinely gained something from classical studies, yet tracing his career from beginning to end, his karmic ties to classical learning were never fully fulfilled. Poetry for Mr. Mao was not his primary pursuit. Rendered through his temperament, it nevertheless displayed remarkable brilliance. Yet the highest path, which a thousand sages cannot transmit -- to possess talent, learning, and temperament in full and yet not become a poet or lyricist of the first rank -- is like a golden lock upon a heavy gate. It cannot be broken by talent, learning, or temperament alone, for talent, learning, and temperament are themselves that golden lock. The same is true of Mr. Mao's poetry."}),"\n",(0,i.jsx)(n.p,{children:"Mao's shi is inferior to his ci -- this was Mao's own assessment. Runzhi's poetry has numerous violations of tonal rules. Though this is a minor flaw, one who cannot cure even minor ailments is certainly no master physician. Those of bold temperament tend to favor bold poetry. Combined with talent, learning, and the circumstances of the times -- when destiny and occasion converge -- heroic works emerge, like a river breaking through dams or mountains collapsing. Done occasionally, this gives full vent to one's nature. But forced repeatedly, it loses its natural quality and ultimately degenerates into mere coarseness. Coarseness has nothing to do with poetry -- it is the bane of literary Chinese."}),"\n",(0,i.jsx)(n.p,{children:"Runzhi's poetry: in the strange and uncanny, far inferior to Li He and Yang Weizhen; in boldness, not equal to Xin Qiji and Chen Weisong -- to say nothing of Tao Yuanming, Li Bai, Du Fu, or Su Dongpo. In truth, Runzhi had no intention of competing with the ancients in poetry. It is only his deluded admirers who, out of excessive love, make such reckless claims. That Runzhi was not of the first rank in poetry does not diminish Mr. Mao as Mr. Mao. To insist otherwise merely adds another laugh for posterity."}),"\n",(0,i.jsx)(n.p,{children:"There are rumors in the world claiming that Runzhi's poetry was largely ghostwritten -- for instance, that \"Qinyuanchun: Snow\" was actually written by Hu Qiaomu. I once had the opportunity to verify this in person with Hu's children and am confident that these are fabrications by idle gossips. Runzhi's poetry and prose were all his own -- there was absolutely no ghostwriting."}),"\n",(0,i.jsx)(n.p,{children:'I compose a "Linjiang Xian" to close:'}),"\n",(0,i.jsxs)(n.p,{children:["Turbid waters tilt in waves for thirty thousand li;",(0,i.jsx)("br",{}),"\nsolemn, I sit alone on a solitary peak.",(0,i.jsx)("br",{}),"\nThe dragon lies hidden, the lion asleep, awaiting the gale;",(0,i.jsx)("br",{}),"\nthe heartless are all mere upstarts,",(0,i.jsx)("br",{}),"\nthose with tears are heroes too."]}),"\n",(0,i.jsxs)(n.p,{children:["A long sword leans against heaven, where stars and constellations blaze;",(0,i.jsx)("br",{}),"\npast and present pass before the eyes into emptiness.",(0,i.jsx)("br",{}),"\nHeaven and earth, looked up to and down upon, are left to fortune and hardship;",(0,i.jsx)("br",{}),"\nhalf a moon hangs above the blue sea,\na single reed-skiff heads east on the great river."]})]})}function u(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,n,t){t.d(n,{R:()=>r,x:()=>s});var o=t(96540);let i={},a=o.createContext(i);function r(e){let n=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),o.createElement(a.Provider,{value:n},e.children)}}}]);